BEGIN;
CREATE TABLE recipes.recipes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),summary text NOT NULL DEFAULT '',base_servings numeric(18,6) NOT NULL CHECK(base_servings>0),prep_minutes integer NOT NULL DEFAULT 0 CHECK(prep_minutes>=0),cook_minutes integer NOT NULL DEFAULT 0 CHECK(cook_minutes>=0),source_note text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id));
CREATE TABLE recipes.ingredients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),recipe_id uuid NOT NULL,position integer NOT NULL DEFAULT 0,section_name text NOT NULL DEFAULT '',name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),quantity numeric(18,6) CHECK(quantity>0),unit_code text REFERENCES core.units(code),quantity_note text NOT NULL DEFAULT '',preparation_note text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,recipe_id) REFERENCES recipes.recipes(household_id,id) ON DELETE CASCADE);
CREATE INDEX ingredients_recipe ON recipes.ingredients(household_id,recipe_id,position,id);
CREATE TABLE recipes.steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),recipe_id uuid NOT NULL,position integer NOT NULL DEFAULT 0,instruction text NOT NULL CHECK(length(instruction)>0),timer_seconds integer CHECK(timer_seconds>0),created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,recipe_id) REFERENCES recipes.recipes(household_id,id) ON DELETE CASCADE);
CREATE TABLE recipes.tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(household_id,name));
CREATE TABLE recipes.recipe_tags(household_id uuid NOT NULL REFERENCES core.households(id),recipe_id uuid NOT NULL,tag_id uuid NOT NULL,PRIMARY KEY(household_id,recipe_id,tag_id),FOREIGN KEY(household_id,recipe_id) REFERENCES recipes.recipes(household_id,id) ON DELETE CASCADE,FOREIGN KEY(household_id,tag_id) REFERENCES recipes.tags(household_id,id) ON DELETE CASCADE);
GRANT USAGE ON SCHEMA recipes TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA recipes TO household_app;
COMMIT;
